-- Create a share for cross-unit collaboration
CREATE SHARE finance_share;

-- Grant database and schema usage to the share
GRANT USAGE ON DATABASE finance_gold TO SHARE finance_share;
GRANT USAGE ON SCHEMA finance_gold.public TO SHARE finance_share;

-- Grant select on specific tables
GRANT SELECT ON TABLE finance_gold.public.orders_daily TO SHARE finance_share;
GRANT SELECT ON TABLE finance_gold.public.revenue_summary TO SHARE finance_share;

-- Add accounts to the share (within the same organization)
ALTER SHARE finance_share ADD ACCOUNTS = <ACCOUNT_LOCATOR_1>, <ACCOUNT_LOCATOR_2>;

-- Check column cardinality to identify candidates
SELECT APPROX_COUNT_DISTINCT(customer_id) FROM finance_gold.orders_daily;

-- Enable equality search optimization on high-cardinality column
ALTER TABLE finance_gold.orders_daily ADD SEARCH OPTIMIZATION ON EQUALITY(customer_id);
